   if(t.id==='IMP-42'&&m.evidence==='E2518')s='Move the existing empty CompletedBy/CompletionDate defaults and CompletionNotes check before native completion. Add resolved performer/date and future-date checks, then complete, maintain IsCompleted and invoke Refresh Inspection Action Classification.';
