   if(t.id==='IMP-43'&&['E2702','E2706'].includes(m.evidence))s=m.evidence==='E2702'?'Replace the numeric rejection-comment comparison with nonblank RevieweComments validation before Return to InspectioninProgress; rerun source/readiness/results on approval and remove open-Finding closure blocking. Add AcceptedAt/release/classification integration only in final-approved branches.':'Replace the numeric rejection-comment comparison with nonblank RevieweComment1 validation before Return to ActionsPending; rerun source/readiness/results on approval and remove open-Finding closure blocking. Add AcceptedAt/release/classification integration in the approved final-completion branch.';
